    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut k: int = 0
    let mut first = true
    let mut words: Vec<string> = []
    for line in text.lines() {
        if first {
            first = false
            k = line.trim().parse::<int>().unwrap_or(0)
            continue
        }
        let mut cur = ""
        for c in line.chars() {
            if c.is_ascii_alphanumeric() {
                cur = cur + c.to_string().to_lowercase()
            } else {
                if cur != "" {
                    words.push(cur)
                    cur = ""
                }
            }
        }
        if cur != "" {
            words.push(cur)
        }
    }
    words.sort()
    let mut items: Vec<(string, int)> = []
    let mut i = 0
    let n = words.len()
    while i < n {
        let w = words[i]
        let mut j = i
        while j < n && words[j] == w {
            j += 1
        }
        items.push((w, (j - i) as int))
        i = j
    }
    items.sort_by(|a, b| {
        if a.1 != b.1 {
            return b.1.cmp(a.1)
        }
        return a.0.cmp(b.0)
    })
    let mut printed: int = 0
    for it in items {
        if printed >= k { break }
        println("${it.0} ${it.1}")
        printed += 1
    }
}

